import os, json
try:
    import pymysql
except Exception:
    pymysql = None

LABELS = {
    '标识符长度限制': ['集群名','租户名','用户名','标识符长度','最大长度'],
    'ODP(OceanBase Database Proxy) 连接限制': ['ODP','OceanBase Database Proxy','连接限制'],
    '单个表的限制': ['单个表','行长度','列数','索引个数','最大限制'],
    '字符串类型限制': ['VARCHAR','字符串','字符','最大长度'],
    '功能使用限制': ['物理备库','功能使用限制','限制'],
}

def _connect():
    sock = os.getenv('MINIOB_SERVER_SOCKET','')
    if not sock: raise RuntimeError('缺少 MINIOB_SERVER_SOCKET')
    if pymysql is None: raise RuntimeError('未安装 pymysql')
    return pymysql.connect(host='localhost', user='root', password='', unix_socket=sock, autocommit=True)

def _ensure(conn):
    with conn.cursor() as c:
        c.execute("CREATE TABLE IF NOT EXISTS ob_docs (id INT, path STRING(512) NULL, title STRING(256) NULL, content TEXT NULL, embedding VECTOR(1024) NULL)")
        c.execute("CREATE VECTOR INDEX IF NOT EXISTS idx_ob_docs_vec ON ob_docs { embedding } WITH { TYPE = IVFFLAT, DISTANCE = COSINE_DISTANCE, LISTS = 100, PROBES = 10 }")

def _search(conn, qvec, k):
    vec_lit = json.dumps(qvec, ensure_ascii=False)
    sql = ("SELECT path, title, content, DISTANCE(embedding, TO_VECTOR(%s), 'COSINE') AS score FROM ob_docs ORDER BY score ASC LIMIT %s")
    with conn.cursor() as c:
        c.execute(sql, (vec_lit, int(k)))
        rows = c.fetchall()
    cands = []
    for r in rows:
        cands.append({'path': r[0], 'title': r[1], 'content': r[2], 'score': float(r[3]) if r[3] is not None else 1e9})
    return cands

def _classify(question, contexts):
    q = (question or '').lower()
    out = []
    for lab, keys in LABELS.items():
        if any(k.lower() in q for k in keys): out.append(lab)
    if not out:
        joined = ('\n'.join(contexts)).lower()
        for lab, keys in LABELS.items():
            if any(k.lower() in joined for k in keys): out.append(lab)
    seen, res = set(), []
    for x in out:
        if x not in seen: seen.add(x); res.append(x)
    return res

# Langflow 入口
# params: { 'question': str, 'embedding': [float], 'k': int }

def run(question: str, embedding: list, k: int = 5, **kwargs):
    conn = _connect()
    _ensure(conn)
    cands = _search(conn, embedding, k or 5)
    contexts = [ (c.get('title') or '') + ' ' + (c.get('content') or '') for c in cands ]
    facts = _classify(question, contexts)
    return {'candidates': cands, 'support_facts': facts}

# 解析 MiniOB 结果为上下文与支持事实
# 入参: results: dict = { 'candidates': [...], 'support_facts': [...] }

import json

def run(results: dict, **kwargs):
    cands = (results or {}).get('candidates') or []
    support = (results or {}).get('support_facts') or []
    parts = []
    for c in cands:
        t = (c.get('title') or '').strip()
        x = (c.get('content') or '').strip()
        if t: parts.append(t)
        if x: parts.append(x)
    context = '\n\n---\n\n'.join(parts[:10])
    # 在上下文末尾附带标签，提示大模型原样抄写
    context += '\n\nSUPPORT_FACTS_TAGS: ' + json.dumps(support, ensure_ascii=False)
    return { 'context': context, 'support_facts': support }
